+
+    // Parse request body
+    const body = await request.json();
+    const { token } = body;
+
+    if (!token) {
+      return NextResponse.json({ error: 'Invitation token is required' }, { status: 400 });
+    }
+
+    // Find invitation by token
+    const { data: invitation, error: findError } = await supabase
+      .from('staff_members')
