+// =============================================================================
+// GET /api/shipping/track/[trackingNumber] - Track a shipment
+// =============================================================================
+
+export async function GET(
+  request: NextRequest,
+  { params }: { params: Promise<{ trackingNumber: string }> }
+) {
+  try {
+    const { trackingNumber } = await params;
